INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1095c192-b979-4bc4-8e5b-81ce9cd997ec', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Filesystem Inspector', 'After mounting, create /mnt/data/test.txt with "hello". Run: lsblk -f | head -3. What filesystem type is shown for your loop device?', 100, '$2b$10$9vOEA/E7RtR2/PXXx0URJe70yIqzk2k6IUHgllVY7ckziXcdwHr.m'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0fda571b-ce83-4689-8089-1dbde3c757cc', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'LVM Creator', 'Create 2 loop devices (dd if=/dev/zero of=/tmp/disk1.img bs=1M count=50, same for disk2). Create PV: pvcreate /tmp/disk1.img /tmp/disk2.img. Run: pvdisplay | grep "PV Name" | wc -l. How many PVs?', 100, '$2b$10$yM1UOSXhQ1xmWcWHG/PxOOGhkfzX1WNSNXnPYbS1pyonjA0wjQU4m'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('58c96f39-7a3e-4765-b52d-35f4dd97a5e0', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'VG Builder', 'Create volume group: vgcreate myvg /tmp/disk1.img /tmp/disk2.img. Run: vgdisplay myvg | grep "PE Size". What is the PE size?', 100, '$2b$10$nuUYOpN3UGiztMBLoVcM1OAOHC6.jAAD8uZ8MbFnKnfylp4xg.iZS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('70db1157-5680-4373-b86a-4059fd7b0416', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'LV Crafter', 'Create logical volume: lvcreate -L 30M -n mylv myvg. Run: lvdisplay /dev/myvg/mylv | grep "LV Size". What is the size?', 100, '$2b$10$cJrRymYXG4SF5wSP97s8JudZygnAkP69KNrZclKfgE8RB1uV8dw9u'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7f260678-2c44-4ab1-8c95-683485ff49a0', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'RAID Builder', 'Create RAID0: mdadm --create /dev/md0 --level=0 --raid-devices=2 /tmp/disk1.img /tmp/disk2.img 2>/dev/null; Run: cat /proc/mdstat | grep md0 | awk "{print $4}". What is the status?', 100, '$2b$10$.Po1/z6FutpwSrPy/4WwO.m0MnfaZLjqGKa9iKQARA4E2R3lAlnYq'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dc0638fa-7bf6-4758-a9b7-4ea8e35821b5', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Swap Creator', 'Create 50MB swap: dd if=/dev/zero of=/tmp/swap.img bs=1M count=50 && mkswap /tmp/swap.img && swapon /tmp/swap.img. Run: swapon --show | wc -l. How many swap devices (minus header)?', 100, '$2b$10$1fBnVXhOetDFvDMqmvcI3OSbZ6O19uAkGjpvhfTA7nGUen5aSL2ym'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bb12d9dd-dab0-4769-b4e7-770f98874a44', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'DF Detective', 'Run: df -h --output=source,size,used,avail,target | grep tmp | head -1. What is the mount point?', 75, '$2b$10$iohxAN3gJUzdwrUWM56hb.P9XE.I.qZ1q3YUvp.5wvSOdLsrsum6m'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d03f1cbf-d6b9-44fb-bbf8-580694c2faaf', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fstab Editor', 'Add to /etc/fstab: /tmp/disk.img /mnt/data ext4 loop 0 0. Run: grep "/mnt/data" /etc/fstab | awk "{print $3}". What filesystem type is listed?', 100, '$2b$10$afZyrniiCeOa6uDRrlzF..LfXFJdFu50h4IaaL72ZdJIj7xFEfXyS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b0fbfe72-47a6-489a-afac-4f84c85fc32f', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Inode Counter', 'Run: df -i / | tail -1 | awk "{print $4}". How many free inodes?', 100, '$2b$10$7giUbOCYdHbuPJCMleKnlOJSV2TsI237f52G/kslg6pKGsiYPCqQ2'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c2d2fe33-c299-4967-97fb-81e64c6b3c5c', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Du Analyzer', 'Create files in /mnt/data (dd if=/dev/zero of=/mnt/data/bigfile bs=1M count=10). Run: du -sh /mnt/data | awk "{print $1}". What is the size?', 100, '$2b$10$rf6m5IKhJjGjh5Zjd4pu9ODXOvrVUkHuwXZwwDwRvWovJ05qIRATe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('73711057-6dad-417b-b7f4-945b1a30912f', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'UUID Finder', 'Run: blkid /dev/loop0 2>/dev/null | grep -o "UUID=\"[^ ]*\"" | head -1. What is the UUID format? (just answer "uuid" if you can see it)', 75, '$2b$10$3QHEVIhwABIxo97YU7bD6.I5BPVWYYJt1cybPAq1i0FdZQMYFCf26'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e305e619-569c-4849-8223-4bfe759e441b', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fdisk Explorer', 'Run: fdisk -l /tmp/disk.img 2>/dev/null | head -5. What disk identifier type is shown?', 100, '$2b$10$5rjiG86v9t2DdWes/U3DCOUDQye0NreOxtqGLLJFH5zaKgvnLTt6u'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6f02db95-65d5-482e-944e-9bd8df382fee', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Cleanup Crew', 'Run: umount /mnt/data && losetup -D && vgremove -f myvg 2>/dev/null; echo "storage_done". What is the output?', 75, '$2b$10$Brw3jMBGQpMH7UCmK0sOruQl5LJq3tLZcpGugnh8cYH1AUbcH3gD.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('40f64f27-2233-42b4-8c5a-34f4aa14e7e8', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Tar Crafter', 'Create /home/student/backup_data/ with 3 files (a.txt, b.txt, c.txt). Pack: tar czf /tmp/backup.tar.gz -C /home/student backup_data. Run: tar tzf /tmp/backup.tar.gz | wc -l. How many entries?', 75, '$2b$10$cKnxRWMW3/nPUJmHVLkkRuX579H.XI8gD76na7pdD2UaWHiTq7miW'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c942e176-7603-48ce-a318-faf97883a430', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Scheduler', 'Add cron job: echo "0 * * * * echo backup_ok > /tmp/cron_proof" | crontab -. Run: crontab -l | wc -l. How many cron entries?', 75, '$2b$10$rP5uiDsDe3CCIc2t7C.Fsu55B4.8k5o3Ki.x69fvlqMMwigLCuIvi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fe0dbca2-703d-4cfa-951b-60a0cd9698a4', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Restore Tester', 'Create /tmp/restore_dir/. Extract backup: tar xzf /tmp/backup.tar.gz -C /tmp/restore_dir. Run: ls /tmp/restore_dir/backup_data/ | wc -l. How many files restored?', 100, '$2b$10$XJnPdHbzEkide1WyEf35qOyb8njlJwvydejFC.kzz9C0ZEW4tZWpm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('339cb176-4682-4361-b9a4-3d0e282ec48a', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Incremental Creator', 'Create new file d.txt. Create incremental: tar czf /tmp/incr.tar.gz -C /home/student/backup_data --newer=a.txt . Run: tar tzf /tmp/incr.tar.gz. What file is listed?', 100, '$2b$10$HiK73lCpJRPfX4wFiCBNp.lZmY9x9fuh2DpNyU0hwRRiHQE9Ti0tu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('709751a4-c092-497e-ba41-16ac45c74f33', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'rsync Master', 'Create /tmp/src_dir/ and /tmp/dst_dir/. Create file in src. Run: rsync -av /tmp/src_dir/ /tmp/dst_dir/ && ls /tmp/dst_dir/. What file is synced?', 100, '$2b$10$8tZQPzW93aTF3YMG8AQZh.BaEaclEp/mime1brpIBk/qwQwDdZJn6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f660a3b0-a6ec-4a79-ba34-bf15a20fbcce', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Exclusion Expert', 'Create files: log.txt, data.csv, log2.txt. Run: tar czf /tmp/no_logs.tar.gz --exclude="log*" -C /home/student/backup_data . Run: tar tzf /tmp/no_logs.tar.gz | grep -c log. How many log files included?', 100, '$2b$10$y/zR/XzKOH/kCHt6P4lyQeSHXsV1A92qqER8eqax0LutMH99PmRHi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cd3a113d-7616-4a84-be3e-2a1dbc7b81ff', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Compression Pro', 'Compare: tar czf /tmp/gz.tar.gz -C /home/student/backup_data . vs tar cJf /tmp/xz.tar.xz -C /home/student/backup_data . Run: ls -la /tmp/gz.tar.gz /tmp/xz.tar.xz | awk "{print $5, $9}". Which is smaller?', 100, '$2b$10$GvQfnvL6m6Be.lz.O46CnOMp8IJoftJdECdyoid9pr6ILaVswBCrm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5ce4647c-f5df-49e4-a9dd-80bbd48db1a7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Verify Expert', 'Run: tar tzf /tmp/backup.tar.gz > /tmp/list.txt && md5sum /tmp/list.txt. What is the first 8 chars of the hash?', 100, '$2b$10$U.z4IIuZPjKFlvdedJ.8Pe4HPxnLJ3SVzofQ0a3Kikzy7ChOn3j6W'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2e332217-5e25-405a-b2c5-f085f9839df0', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Docker Backup', 'Run: docker run -d --name db-backup alpine:3.18 sleep 300. Then: docker export db-backup > /tmp/container_backup.tar && wc -c /tmp/container_backup.tar. How many bytes (approximately)?', 100, '$2b$10$OjBpuQyGhfleOiJ3FfD4kOsgJiHcEqLfzPkaydrL.EfOKb0oTFObu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('63959e80-0a15-4105-ad96-9f50f8de8f6c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Checker', 'Run: cat /var/spool/cron/crontabs/root 2>/dev/null | head -1. What is the cron schedule?', 75, '$2b$10$sTGLVEnVSi2KJtv9O.8OqOvRSAdJtgqZfIaN/ust28NE88wkxwRG.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('93107ae7-14eb-4d75-8d66-fd4052aae26f', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Diff Backup', 'Create /tmp/original/file.txt with "old". Copy to /tmp/backup_version/. Change original to "new". Run: diff /tmp/original/file.txt /tmp/backup_version/file.txt. What is shown?', 100, '$2b$10$ToSdvmSUmu3ex2zCOhx2TOxzOWg7WRjqXOVpIp2V02QLiG/9p2/1q'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d5acd945-ef38-4fb3-a9a9-8ae18f132903', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Archive Inspector', 'Run: file /tmp/backup.tar.gz. What is the detected type?', 75, '$2b$10$yi2HFiCOXldFIav2t2PDteKUP0tE.tVCt4krhJNLzypTCis.8KSjy'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('be961524-563f-4ca7-9972-87a7eb21eaf7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cleanup Script', 'Create /home/student/cleanup.sh that removes /tmp/restore_dir, /tmp/incr.tar.gz, /tmp/gz.tar.gz, /tmp/xz.tar.xz and echoes "cleaned". chmod +x and run. What is the output?', 100, '$2b$10$IyQ5bvUe6OrBUdu0xoKHl.m7B7t5FSwO4AFr5IBYVxkNwgPKHUjJ6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('72383643-0290-48d8-b4ee-ae665dfe4836', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Checksum Verifier', 'Run: sha256sum /tmp/backup.tar.gz | awk "{print $1}" | wc -c. How many characters is the SHA256 hash?', 75, '$2b$10$Cgp.HgvtQI0H8EVKnbDKhuaMkS4IZrFas/YZYFt.BmJvFAPAnRare'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a7fd0303-f945-4103-b467-deca0c16425b', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Date Stamped Backup', 'Run: tar czf /tmp/backup_$(date +%Y%m%d).tar.gz -C /home/student/backup_data . && ls /tmp/backup_*.tar.gz | wc -l. How many date-stamped backups?', 100, '$2b$10$VFJiQ8YDpAanOUwplnHapuN8CAv3fe7FqE1K/Seif5nt4Cz5TN8aG'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ba278c42-0fbb-45c1-a88a-5b8e21bde8af', '884ee166-21d8-4336-a519-6ccdf111068c', 'iptables List', 'Run: iptables -L -n | head -3. What is the first chain name shown?', 50, '$2b$10$c9.dAn1H6utLgtz/YHaOBOSG0vD53JSymUYumZ27YzEe7aqLCbdte'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('84ee227f-9a14-4bd0-809d-5c4368ae54bf', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Creator', 'Run: iptables -A INPUT -p tcp --dport 8080 -j ACCEPT && iptables -L INPUT -n | grep 8080. What target is shown?', 75, '$2b$10$mMv2yorsJUXW4XvCOVhmQ.LYZ2b2owFEVUqxAD6FgBobJMoDcO7ra'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0bbac76c-d656-4e3d-b92e-b5a518997944', '884ee166-21d8-4336-a519-6ccdf111068c', 'Port Blocker', 'Run: iptables -A INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep 9999. What target?', 75, '$2b$10$Dg/ihjUwqxLA7Qciqp3j5uirTgyZ8wcW2qxTyZYF2vGfmHuIv/74i'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a5b27a6c-4129-4398-83ac-f94375e8ca8e', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Deleter', 'Run: iptables -D INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep -c 9999. How many rules for port 9999?', 100, '$2b$10$/vWcMHkJFJJqWrW.Io5wFOr2q2ANOwKEkpgZSEeQz/dRi4cOg5bK.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f1a51630-40cd-4420-9f0c-cc5ada2d76c6', '884ee166-21d8-4336-a519-6ccdf111068c', 'Chain Creator', 'Run: iptables -N MYCHAIN && iptables -L | grep MYCHAIN. What chain name appears?', 100, '$2b$10$DllXUwo.VZuUUhgp00ktfOG3bhLXnNJhbb0ZhckiA2je8ibB29lQy'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ae75d4b8-57dd-45bc-9c92-22dac2b9bc23', '884ee166-21d8-4336-a519-6ccdf111068c', 'IP Blocker', 'Run: iptables -A INPUT -s 10.10.10.10 -j DROP && iptables -L INPUT -n | grep 10.10.10.10. What target?', 100, '$2b$10$uuBP1LNC7IkmT3w0nNT8Eecr3dtk2Le/VlLot.N/4GNKklhKDNsK.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('74357580-d0af-4a06-aaff-c15db06dd45c', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rate Limiter', 'Run: iptables -A INPUT -p tcp --dport 80 -m limit --limit 10/min --limit-burst 20 -j ACCEPT && iptables -L INPUT -n | grep "limit:10/min". Is limit shown? (yes/no)', 100, '$2b$10$KIbHRbrERaFnJC3sprcogeERtX9829yUUF9om99Hn/zSETMHcMAuS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a9da7e74-5ccc-42e1-a192-71880ff06a98', '884ee166-21d8-4336-a519-6ccdf111068c', 'State Inspector', 'Run: iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT && iptables -L INPUT -n | grep ESTABLISHED. What states are listed?', 100, '$2b$10$.x/PKBtvCgcP4wsgaX9P0eiPwXMjGIB8GH69ncAxwIienW0ZRj7oa'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('aef22a11-c7c4-46b5-935b-e6648cfe4ea8', '884ee166-21d8-4336-a519-6ccdf111068c', 'NAT Creator', 'Run: iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80 && iptables -t nat -L PREROUTING -n | grep 8080. What target?', 100, '$2b$10$pZFnZi.3eLUWU5U.Kk/M5O5Hkb0WBzqv.lKoq1sR5oNPNEsWSRWiS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5e601084-e681-4561-b03c-f07f42346f22', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Saver', 'Run: iptables-save > /tmp/iptables_rules.txt && wc -l /tmp/iptables_rules.txt. How many lines of rules?', 100, '$2b$10$CSH9lJyYpTKqxWz4S5sqTus4USBwt3gE4noht7HQhstwtwgsbXHeK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b1635c35-d4c1-45af-80ce-d66c11ebcbc3', '884ee166-21d8-4336-a519-6ccdf111068c', 'Log Logger', 'Run: iptables -A INPUT -p tcp --dport 8080 -j LOG --log-prefix "FIREWALL: " && iptables -L INPUT -n | grep LOG. What log prefix is shown?', 100, '$2b$10$G5IOd/F0IWLtrWSm.JDl5OwG/ic1S/0EXcHcHfjbzTp8NzfoDeVLi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('24eca6da-667f-4e7e-aa1c-10a530f7f5db', '884ee166-21d8-4336-a519-6ccdf111068c', 'Interface Binder', 'Run: iptables -A INPUT -i eth0 -j ACCEPT && iptables -L INPUT -n | grep eth0. What interface is shown?', 100, '$2b$10$IBLkOFWgiFvlXe4gfv5vxOR/IFfVCtCumCDpuhR.flhIEyoeQoXLq'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6d93feba-19b6-44cc-b384-16ec1c048c82', '884ee166-21d8-4336-a519-6ccdf111068c', 'Packet Counter', 'Run: iptables -Z INPUT && iptables -L INPUT -v -n | head -3. What is the pkts count for INPUT chain?', 100, '$2b$10$W7cCmy0kXEOPDClWHHtuLeaS3F90/ID5fEkFFLLLDlxk3lHSVh8OC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dded8a8f-b8ad-4dfb-8c34-3a32004e4643', '884ee166-21d8-4336-a519-6ccdf111068c', 'Flush Master', 'Run: iptables -F MYCHAIN && iptables -L MYCHAIN -n | wc -l. How many rules in MYCHAIN after flush?', 75, '$2b$10$7eM0ODjiS9SqmxTdZBb/HuJfiABBrh3qxrZwXya0Jur3z9451Y8pu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('27125134-546c-4a92-8725-6474d5bf3251', '884ee166-21d8-4336-a519-6ccdf111068c', 'Cleanup', 'Run: iptables -F && iptables -X MYCHAIN 2>/dev/null; iptables -t nat -F PREROUTING 2>/dev/null; echo "firewall_done". What is the output?', 75, '$2b$10$ZbgP5GriMKulQ6nCcqWgk.q21.1YUNo7.FvNDitd97Q1lBjNZdUha'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b02da11f-0bc1-4360-8cd9-813c30d515b8', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Creator', 'Create zone file: /etc/bind/zones/aeroacademy.local. Add SOA record for aeroacademy.local. Run: named-checkzone aeroacademy.local /etc/bind/zones/aeroacademy.local 2>&1 | tail -1. What is the status?', 75, '$2b$10$O.HAx9djFEfbXhWgR/NOS.noiIWJ8SQ8svpqR5V94OHObvaPSyUDe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b2ac5b90-a2a8-4f36-8c52-a3044f22db8e', 'e0decd06-4a2e-4f94-965a-79854928514d', 'A Record', 'Add A record: aeroacademy.local IN A 192.168.1.100. Run: grep "IN A" /etc/bind/zones/aeroacademy.local. What IP is shown?', 75, '$2b$10$aQTEuskWKwQpPUm2XLcST.f06UnUs7SFu8uvjn9ZRLHRNzqpwVwqe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5bf1cded-9bcb-44ef-8366-dfb986dafebf', 'e0decd06-4a2e-4f94-965a-79854928514d', 'MX Record', 'Add MX record: aeroacademy.local IN MX 10 mail.aeroacademy.local. Run: dig MX aeroacademy.local +short. What is the mail server?', 100, '$2b$10$JdFWhFrJW0j5t5JgzunIVeHSftVJ75IOQFtJlvWoPmKLGhUaKGEDm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f5b6e6ee-9a50-4282-881e-90391280b526', 'e0decd06-4a2e-4f94-965a-79854928514d', 'CNAME Record', 'Add CNAME: www.aeroacademy.local IN CNAME aeroacademy.local. Run: dig www.aeroacademy.local +short. What does it resolve to?', 100, '$2b$10$PLtPP8IBnEaslcIAp32V5Ox4863POwF/q2y.98ch5/xely6.a8sgC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('245ac7e3-4f53-40ce-b570-e1962e846ba4', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Reverse Zone', 'Create reverse zone for 1.168.192.in-addr.arpa. Add PTR: 100 IN PTR aeroacademy.local. Run: named-checkzone 1.168.192.in-addr.arpa /etc/bind/zones/reverse.local 2>&1 | tail -1. What status?', 100, '$2b$10$8ZnIP4rLMC8LDkz9Qvro0e1YWR7MB9Sd.m2gY8Ko/3h3i1IXCVT/q'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a141e616-1dcc-460a-b2f0-fd605fe82e65', 'e0decd06-4a2e-4f94-965a-79854928514d', 'NS Record', 'Add NS record: aeroacademy.local IN NS ns1.aeroacademy.local. Run: dig NS aeroacademy.local +short. What nameserver is shown?', 100, '$2b$10$0gqGkkoVqZ.25oiaZ7.OQuoAM4sGYbvrtk2QBMr66re2F3h.7BT.y'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a0a1a09b-79e5-4f25-9141-c733f9c7978a', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TXT Record', 'Add TXT record: aeroacademy.local IN TXT "v=spf1 mx -all". Run: dig TXT aeroacademy.local +short. What is the TXT value?', 100, '$2b$10$IMQTxmdQniXU3sDqhRM94..BNP4VEiQ8OUUlE/Pqjts7Bjt6LHj8m'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('26e98073-0de8-4bef-be21-bb6459ed9a9f', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Inspector', 'Run: cat /etc/bind/named.conf.local | grep "zone" | wc -l. How many zones are defined?', 75, '$2b$10$xSqXvFQ8S.ciwMMaL3gJnucZUHiZcMRliIgf5oypWZEA6oPOHxSg2'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('25b46a08-17cd-469b-a79d-8f3f44814c23', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Serial Bumper', 'Update SOA serial to 2024010101. Run: grep serial /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the serial number?', 100, '$2b$10$F79665b7N4KSrKwTNlx3wu/DhKCmzHm5ms2GqMvd6GoD.Qv8aW3Eq'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('30184898-446d-44ae-a2fe-17bef2cb1ff7', 'e0decd06-4a2e-4f94-965a-79854928514d', 'TTL Set', 'Set TTL to 3600 in the zone file. Run: grep -m1 ";" /etc/bind/zones/aeroacademy.local | awk "{print $1}". What is the TTL?', 75, '$2b$10$HjGbrffcu8iJ.5r0S06WNu5ffMOtcopl1qvLJeikmttXZ9nk/Xcsa'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8bc7b918-5527-45a1-a65e-bb0aa19dbd3b', 'e0decd06-4a2e-4f94-965a-79854928514d', 'AAAA Record', 'Add AAAA record: aeroacademy.local IN AAAA ::1. Run: dig AAAA aeroacademy.local +short. What is the IPv6 address?', 100, '$2b$10$PnM.faUlE/8tiZ.fFQHByu44QMhG7.GpQhjegmmPMe0/gSMpdwWF6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dbc65521-ce4b-485f-a3c4-e8cf32c206b2', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Wildcard Record', 'Add wildcard: *.aeroacademy.local IN A 192.168.1.100. Run: dig random.aeroacademy.local +short. What IP resolves?', 100, '$2b$10$1xhxGgm5xSS5ElNhQEF/2uXsFAACL4GkS1CncihZffYr9EKI7jRi.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('53759303-6342-4360-98fe-c1a252d6f6a5', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Config Validator', 'Run: named-checkconf /etc/bind/named.conf 2>&1. What is the output (empty means OK)?', 75, '$2b$10$qz3tELMNxNk/UUH0rqi9tO02.YdKLCMzM46vnjaKo1qea9j.cALHi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cd7a5eff-3a5e-4969-9582-a39c80f72c35', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Dumper', 'Run: dig axfr aeroacademy.local @localhost 2>&1 | wc -l. How many lines in zone transfer?', 100, '$2b$10$uiGzDnvbbAoRp9gHLC74v.NkVPCDRZOjQbU0YMrE4e0NNJZC8U97q'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2bd4558d-f631-4e34-a64f-0c4cd1c4a689', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Cleanup', 'Run: systemctl stop named 2>/dev/null || service named stop 2>/dev/null; echo "dns_done". What is the output?', 75, '$2b$10$5fIbhwdLFY668V/YfbO62OuPY2HsujFuwqpeNxHRVr5dPQJGdP88y'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ac230810-469f-4a11-8e73-b2cda5cfb40e', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Repo Creator', 'Run: mkdir /home/student/myrepo && cd /home/student/myrepo && git init. Run: ls -la /home/student/myrepo/.git/HEAD. What does it contain?', 50, '$2b$10$/ahA60ExcUbDW7epVX4zPeUqgEzag2Xvq/uRdPwxOpTDuXTCkRUPK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('40034ded-a334-4456-955e-2a5d967889d8', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Commit Crafter', 'In myrepo, create file.txt with "hello git". Run: git add . && git commit -m "first". Run: git log --oneline | wc -l. How many commits?', 75, '$2b$10$nhZp1QRcrnqqXQlSQvoGPu/8JYiu5caE1OYZZvWKkpb1ygtSMfl02'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6c7df797-30cd-4015-bfe7-719f4b1bcc32', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Branch Master', 'Run: git branch feature && git checkout feature. Run: git branch --show-current. What branch is active?', 75, '$2b$10$BHGbB0npySsFmt1x26zF8uVDL9yvsiOiES6PHiK0tT8hPqdRPDFY.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0b44818d-8311-4ac5-9d14-0e10881efc4b', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Merge Pro', 'On feature branch, edit file.txt to "feature edit". Commit. Switch to main, merge feature. Run: git log --oneline | wc -l. How many commits now?', 100, '$2b$10$toIUGqaph8vGn7TvrIUA6Orz/UvcAGGgsVHyRzGsxIgekxUhca/ga'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b37058b4-50d3-4d30-9b24-05ee25fa0911', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Diff Detective', 'Edit file.txt to "changed". Run: git diff --stat. What file shows as changed?', 75, '$2b$10$3aW4q5DMb7oBNkjxRPhX4eNTmwss7eikvKuUiVUCbJAY78yWFOAzq'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2cf6a09d-0464-4be7-961e-930d3a591312', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Stash Expert', 'Make uncommitted changes. Run: git stash && git stash list | wc -l. How many stashes?', 100, '$2b$10$fnm0WUhbk.XywqD9LUmBLukX9Jyc/xgw90HtE3GS0YNXl217tDB5W'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('737c28d1-1d88-419a-9f39-65b0dc89b17a', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Tag Master', 'Run: git tag v1.0 && git tag -l | head -1. What tag is listed?', 100, '$2b$10$6Q88tKFcpusPelREVyGEJ.jUhA.weG2ee2J7JpyWd4XDeRKW7EVpu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('240441fb-e2cd-47d1-bd13-a27c4f1d5900', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Remote Connector', 'Run: git remote add origin /tmp/remote.git && git remote -v | head -1. What URL is shown?', 100, '$2b$10$.jyPKS85CQ/TkW4/LpJPMOPWEMlQVm.rHcSLteZxaWDLONFRl1ixe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3a00228f-ce46-4a58-8246-e04c7c97c86a', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Blame Reader', 'Run: git blame file.txt | head -1. What commit hash is shown?', 100, '$2b$10$IahOy/2ra67vDgXsPzpEJOsl915yG9/HbBKbNWhgOdAB4bvljthHm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9216967f-8013-4bfe-bf9c-8180edc55820', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Log Artist', 'Run: git log --oneline --all | wc -l. How many total commits across all branches?', 100, '$2b$10$51f.eKm.PbT1dIVOVR1ShuEediIJxcUfss8b8BoZaRXgUkQhS9NUC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('edaf8d8e-1f78-406d-9200-a25d946c3729', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Reset Master', 'Run: git reset HEAD~1 && git log --oneline | wc -l. How many commits after reset?', 100, '$2b$10$lir8ptDxd7hT5Bu3ulUlTe.wP7NhcbhHCCSYech5f7ebojK52H1OK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3aa6a77c-e075-49e8-8480-1424ab95525a', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Cherry Picker', 'Create another commit on main. Run: git cherry-pick HEAD && git log --oneline | wc -l. How many commits?', 100, '$2b$10$xjoPuhRL2CRpjGN898L9YOqZRHUgcwpCWBQbyQbQXOOLW4GR1xmnu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4cb72203-e18a-4fff-a830-902ece6e7e20', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Submodule Starter', 'Run: git submodule add /tmp/submod.git modules/sub 2>/dev/null; echo "submodule_done". What is the output?', 100, '$2b$10$gMUQWGlYl96W/cp7msQFvOLQGDn0rHX8xzVoWbuGGU9mimMHAqgPm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fdf344a2-b908-4ef4-9f44-baa5b31a987f', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Config Inspector', 'Run: git config --list | grep "user.name" | head -1. What user name is set?', 75, '$2b$10$TkfnI45rg0yai2JcJ66c4OVZNBtiwCtF83biBm0g5ZY8wcinrKoMO'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1fa8fa04-61a1-4e74-8aed-726de954ed70', 'db2d2817-5c84-4d6e-b1a7-2e1051fee251', 'Cleanup', 'Run: rm -rf /home/student/myrepo && echo "git_done". What is the output?', 75, '$2b$10$3zAO7pVLyNK8Z3.63gYJBOwaADbqthIRXvLWqQSoRPKoLsfe/J2yS'ON CONFLICT DO NOTHING);
