INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('745ba68e-21d0-48ba-994d-f1c60fcb49c8', 'ea46a43d-c6a5-40e9-93bb-e7f40f2a8572', 'Template Crafter', 'Create Jinja2 template /home/student/test.j2 with "Hello {{ name }}". Create playbook that templates it to /tmp/output.txt with name=world. Run: cat /tmp/output.txt. What is the content?', 100, '$2b$10$tvI6riVbLKb85ehtiVFhceNa/V56OesKT1XybfqCiQlfKQfrHpZ52'ON CONFLICT DO NOTHING);
