INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d607627b-6cb7-4a97-a947-5c604ed297e3', 'ea46a43d-c6a5-40e9-93bb-e7f40f2a8572', 'Role Builder', 'Create role structure: roles/myrole/{tasks,handlers,templates}. Create tasks/main.yml with shell echo role_task. Run: ansible-playbook --connection=local -i "localhost," playbook.yml 2>&1 | grep "role_task" | wc -l.', 100, '$2b$10$SBYhWNcC2c5gsqCht7znLOnWE4wWsL/gXJmIZKscg3NLurDMofQhm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9a49a020-0623-41bf-a283-79693ea856a7', 'ea46a43d-c6a5-40e9-93bb-e7f40f2a8572', 'Inventory Inspector', 'Create inventory: [web] localhost ansible_connection=local. Run: ansible-inventory --list 2>&1 | grep "web" | head -1. What group is listed?', 100, '$2b$10$y5eY7BrSKh98BcqWWzLqyer7Oea9jTCEAe/c5SjbyPaNJjpiiusdK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c1ab6976-4a2e-4fc3-bc39-bf847ee6e347', 'ea46a43d-c6a5-40e9-93bb-e7f40f2a8572', 'Vault Master', 'Run: ansible-vault create /tmp/secret.yml --vault-password-file=<(echo "mypass") 2>&1; echo "vault_created". What is the output?', 100, '$2b$10$S1h6PShOU/1igCRhidilQO.QlpAg2sMPUItXBOk.Ur3PIK/.DrN4O'ON CONFLICT DO NOTHING);
