INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6ff73528-dba5-4977-9087-0ead1872f2e6', '19796c88-1a0a-4c0c-ba7d-4422edecb4fe', 'Cluster Cleanup', 'Run: kubectl delete namespace dev 2>&1 && echo "k8s_cleanup_done". What is the output?', 75, '$2b$10$K5sulog2o4Y6tGB6pxjuBev4l8yIkHAhQrpMMIaOQQWvb6m/dJM/.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('39dcaf18-54f4-460c-98e1-ffb10fb4a831', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Package Manager', 'Run: yum list installed 2>/dev/null | head -3 || dnf list installed 2>/dev/null | head -3 || echo "package_manager_available". What package manager is available?', 50, '$2b$10$0F7Vv.b62ce6IW2OZhUjL.XajKdeb16Y0qObjw3QjRaU2tjNfHUJ2'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('51da9c7d-9e42-47a3-a49a-c9847b84d711', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Service Control', 'Run: systemctl list-units --type=service 2>/dev/null | head -3 || service --status-all 2>&1 | head -3 || echo "services_listed". What services are shown?', 50, '$2b$10$eOZ.2LuKPXcGczdWjfjtS.zrJoJJvVk7NozLHrITamw.TVVNj88mC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b2769a4d-b027-4bc8-a911-b2192d762d74', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'SELinux Inspector', 'Run: getenforce 2>/dev/null || echo "selinux_not_available". What is the SELinux status?', 75, '$2b$10$ntTOnYI4G1.PjFELljm2s.Bvq/KcBXMaIfJ3kmw9pbYzVyOD02waK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b2eab5d6-fdc5-4495-be56-7b6d6147e91c', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Firewall Manager', 'Run: firewall-cmd --list-all 2>/dev/null || iptables -L -n 2>/dev/null | head -3 || echo "firewall_checked". What firewall is active?', 75, '$2b$10$8Nna4y3fMkElLYIw7UxSPO2oIWfXJMkyufmCZoL.MTMgHYU6t9j1S'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6773271b-794e-4ba9-985e-e915665bc798', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Yum Repository', 'Create /etc/yum.repos.d/custom.repo with [custom], name=Custom, baseurl=http://example.com/repo, enabled=1. Run: cat /etc/yum.repos.d/custom.repo | grep "name=". What is the repo name?', 100, '$2b$10$TdRWdCsENpIgzXWVT3LJHOAGffPC4gyRFxxDqI1FrHaGHx2lw4V0q'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('61ace8cb-4a91-4508-8313-09d2646bc10a', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Cron Master', 'Create cron: echo "0 2 * * * /usr/local/bin/backup.sh" | crontab -. Run: crontab -l | head -1. What is the schedule?', 100, '$2b$10$8VL9thZEA3qbkcvQtMNpgOfHEAOWxdUaoh0mD1pZBEL3bXnHir2xG'ON CONFLICT DO NOTHING);
