INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('815fef68-63de-4082-8697-ccc617b999a9', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'User Manager', 'Create user: useradd -m devuser && id devuser. What UID is assigned?', 100, '$2b$10$obKRWuHGYvnlSitwtZAaweRIgjC2BOGWaWAyeqLFC8eRM42Tv2TqS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fdc3326c-bd41-499b-b939-30460dd29e84', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Tmpfiles Creator', 'Create /etc/tmpfiles.d/custom.conf with: d /run/custom 0755 root root -. Run: cat /etc/tmpfiles.d/custom.conf | head -1. What path is created?', 100, '$2b$10$3/lMb..63je4XmjHWiQtGemv.9Pbz4MQbGyXF4NqMZ2D8vSKyzhCe'ON CONFLICT DO NOTHING);
