INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bd66c1e8-64a8-4859-b45c-05ed0485a20f', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Disk Partitioner', 'Run: lsblk | head -3. What block devices are shown?', 75, '$2b$10$MWwSodHeaZBc66WRZ9hJ7uboaK4SGSa5Ta0EftiAHxUr2OheuVTVy'ON CONFLICT DO NOTHING);
