INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9d02014b-2bfb-425b-91ae-541e90753aa2', '39444481-c0f1-4af3-9ac9-7223c18963a7', 'Log Viewer', 'Run: tail -5 /var/log/messages 2>/dev/null || tail -5 /var/log/syslog 2>/dev/null || echo "log_viewed". What is the output?', 75, '$2b$10$AX9wklU6n5RWWo1lpzoBh.9M4IRNe8QajnRJFjRlrYhxi1YtE8VXK'ON CONFLICT DO NOTHING);
