INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2f1b5c36-cf63-4ffb-ac4f-99e275fa94a7', 'f6d4f425-9d67-4506-ae35-c713d671e033', 'File Integrity', 'Run: sha256sum /etc/passwd | awk "{print $1}" | wc -c. How many chars in the SHA256 hash?', 100, '$2b$10$KdjG2tcvZl3TuwyaD0BlOehKrCOp1.TRC6./AbtuxvfZbi2QuLUoe'ON CONFLICT DO NOTHING);
