INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('de7c157e-7663-4748-8113-b02b9285aafa', 'f6d4f425-9d67-4506-ae35-c713d671e033', 'Sudo Config', 'Add to /etc/sudoers: student ALL=(ALL) NOPASSWD:ALL. Run: grep "student" /etc/sudoers | head -1. What rule is set?', 100, '$2b$10$NKFy/k8PVrBsS02Bn9nBD.2/odawVhK.FFKmEJpo3fh0GLMn/4Q7O'ON CONFLICT DO NOTHING);
