INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ef4d47a4-71fe-4fed-983b-ade926c195ca', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Process Inspector', 'Run: cat /proc/1/cmdline | tr "\0" " ". What command is PID 1 running?', 50, '$2b$10$FbjqYi4DH8m/lMro.baODeGR25VJnHrOmry4pASDoLMHIPgY.NLLW'ON CONFLICT DO NOTHING);
