INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('68c0a9d4-258c-4e5b-b3e2-93c0fc585e3f', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Script Writer', 'Create /home/student/inspect.sh that outputs exactly CONTAINER_OK. Make executable. Run it. What is the output?', 75, '$2b$10$U.AWyBlj87z9BXJ4sx7k/ejO8Yk66i8ySBk5jPNbm0wEXxHz5h9wK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f879ea25-582d-4728-8589-48684380f488', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Permission Setter', 'Create /home/student/locked.txt. Set to chmod 000. Run: stat -c "%a" /home/student/locked.txt. What number?', 75, '$2b$10$9OWls6Tw1XHsvKZm14drKurvpnRCPChQ/oz14Ce6r6Fz/hNmx2PN6'ON CONFLICT DO NOTHING);
