INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3b76af98-4f44-47ad-bd36-7c8a7c8eef5c', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Date Formatter', 'Run: date +%Y%m%d. What is today date in YYYYMMDD format?', 75, '$2b$10$r3ji4YflKgsqTVUbJMJpReAcU8Sypiw785Uce/uyOZ9xDASHLC26i'ON CONFLICT DO NOTHING);
