INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('1b29123a-c331-452e-a848-06a10f14a4d7', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'File Duplicator', 'Create /home/student/original.txt with "clone me". Copy to /home/student/clone.txt. Run: diff /home/student/original.txt /home/student/clone.txt. What is the output (empty if identical)?', 75, '$2b$10$.sJOTvfxGtCa8gyCR.sxLOq1RbT8/OP3TGeSl3XDBG7GZWgc5ypce'ON CONFLICT DO NOTHING);
