INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('80614c8a-8aa0-4e57-a953-8e4d96899d6b', '8f5af76d-8355-42dd-bbd2-37a10a896dc1', 'Path Resolver', 'Run: realpath /home/student/. What is the absolute path?', 75, '$2b$10$DKAxqbVO7DeMZFmNk/oni.ngIMlfKTPGgZGU0QKijhjPCCnQ6kvdi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b24bffdd-7a0d-4ea9-b405-64ca52840204', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Database Creator', 'Create a database called shopdb. Run: mysql -u root -e "SHOW DATABASES" | grep shopdb. What is the output?', 50, '$2b$10$VYgqzkwPYxNg7QO/rXtZpeyyZ7fUuFnkB.KTWwzu52ZvebvR0D6xO'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('942937c6-cbe7-4287-9cd9-d933b3a2076b', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Table Architect', 'Create table products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50), price DECIMAL(10,2), stock INT DEFAULT 0). Run: DESCRIBE products | wc -l. How many columns (minus 1 for header)?', 75, '$2b$10$/N58KKnLSvCCIhOUvr4NhuZhv1StFY8Qp6wk6Xq0jJdqzuRfyu5y6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('08956510-905e-4cb2-bd42-51ec22f1694d', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$95PZzHbjuNpCbE3Y/YsXxu6y58isu2pi.q.awcxbFHYp.S/JFA8Eu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('138b116a-4015-469e-81b2-343ade3650cc', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product name?', 75, '$2b$10$jXVnlZFS0W30ImZanGxMfOQr5PmB/Z3N2yOdG1UZ2Zw.To4MMkiJ.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bdd1829b-dc1a-40d8-8ef1-ae3466cccb08', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Index Builder', 'Create index on products(name). Run: SHOW INDEX FROM products WHERE Key_name != "PRIMARY" | wc -l. How many non-primary indexes?', 100, '$2b$10$lhXHGSkHwn7x7I7N56tHt.xNB7m7SvfwrUE/dcUdgzw7HTuVoK9v.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('201b0dfb-fd4c-437f-bac2-abd0e3dbd5a8', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'User Manager', 'Create user "appuser"@"localhost" identified by "secret123". Grant SELECT,INSERT on shopdb.*. Run: SHOW GRANTS FOR "appuser"@"localhost" | grep "ON shopdb.*". What privileges are shown?', 100, '$2b$10$EpOxhYlGiWrIi6J2IIcM4e7.vu.X47Y4Pvm99a/oa6zOMwKAos9T6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('11276137-b1b7-476b-8d6b-ea41232c642a', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Backup Creator', 'Run: mysqldump -u root shopdb > /tmp/backup.sql && wc -l /tmp/backup.sql. How many lines in the backup file?', 100, '$2b$10$hBFyjOwABQefFp5mk4qNYuM8tJMYYdWVniu.LkpJVHc5U/R2fv1g.'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('dee3c115-5538-4f3f-82f7-759034eb3500', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Join Artist', 'Create table orders (id INT PRIMARY KEY AUTO_INCREMENT, product_id INT, quantity INT, FOREIGN KEY (product_id) REFERENCES products(id)). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id | wc -l. How many result rows (minus header)?', 100, '$2b$10$82g.Y6xKS6QjeFuSRyfUeuSA9vCuO9mI5mcC3NnmUyDHd8DRs1HXa'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('784849c4-970a-49c3-8a1d-37b4b698b142', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total inventory value?', 100, '$2b$10$xZkBKXPVRa4tcBRhjWyVyuSGGLqAwUU1Gxr.Oxld/Lx44qMYn5ZiW'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('cec2bcf7-fec4-4520-88f3-85a3c0cce05c', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Transaction Tester', 'Run: mysql -u root shopdb -e "START TRANSACTION; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && mysql -u root shopdb -e "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$L1j8k.qpv0ZEeRM/T1wOEOtCUL3jb3tHaTnIrvSFOCoW2Oe52nTOC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('924603c6-008a-4bb3-9941-c3069d35bfcb', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'View Creator', 'Create view cheap_products as SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product appears?', 100, '$2b$10$3R86zJdWClw6DlM0elcFdel5RfRg.NRRt6xE.6oC8FzQ26Ucy0vDO'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('847b1575-3a18-444a-b060-1501610df3ac', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Permission Auditor', 'Run: mysql -u root -e "SELECT user FROM mysql.user" | grep appuser. What user is listed?', 75, '$2b$10$SiVuWmYSARSbjUsb7bO.pu/PuiKd2QOwZAIf2/OIwwMML1CJ.IjGi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('62b6d442-a328-41a5-8298-a60da008da2a', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Schema Inspector', 'Run: mysql -u root shopdb -e "SHOW TABLES" | wc -l. How many tables exist (minus header)?', 75, '$2b$10$SCAeW02yEBEMqwLfukLujunH4UfkWP0zbfc6MbPPAzUr6HaepY7Su'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0cf83bc9-25bc-452c-8b42-c763ca2c5646', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Auto Increment Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$r1Z3oazK180FiwT5JFNQRuBs7ngwSOkNOBeTd2P.2psL8WV4PJlti'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('542569f5-2267-48f9-a90d-a53fd6ffab8a', '11dc0358-43a4-4f7c-b6eb-e12274be5ff9', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name="Mouse" && mysql -u root shopdb -e "SELECT price FROM products WHERE name=''Mouse''". What is the new price (rounded to 2 decimals)?', 100, '$2b$10$Yz7yFViEKnXBqBgG0280c.Eg/5X.kI5vscBgBleKFQCfUKFU8EbDe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e696bc25-3d58-452a-bb23-3de0bc6fc016', '50d6a493-7898-473d-8287-137229593da9', 'Virtual Host Builder', 'Create /etc/nginx/sites-available/mysite.conf with a server block listening on port 9090, root /var/www/mysite. Create /var/www/mysite/index.html with "Hello Custom". Enable the site with ln -s and reload nginx. Run: curl -s localhost:9090. What is the content?', 100, '$2b$10$v8Ljb3iab0bQBTloFeCv2uJRM2BvlyjN9f3cCoPaD37d.iNcTl6DK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('81cfe365-f508-4335-8a5f-53a8f760c03a', '50d6a493-7898-473d-8287-137229593da9', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$gaq8tx8A8WcBj.7ke8Izj.kbbaSZqu8sbwsVUOvTMvLNCIeQHGU7K'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8b596896-97f7-46cf-b0fa-6042e3c618e9', '50d6a493-7898-473d-8287-137229593da9', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$HPIkvEnKjnyaaNER1rBbd.vQtp3H/xkby2n.mUjGoWkH9RSlnuZQm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5527c7c7-6c5a-44d9-9749-1f696324a0a5', '50d6a493-7898-473d-8287-137229593da9', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$r3AFAfn2wVpdUeftlkP4luHq8eK1LOKx2DcuiKtBuQjeJr2LarppS'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9cd25815-0167-48f3-9fe1-f33cbac779b4', '50d6a493-7898-473d-8287-137229593da9', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$FYRNNDv5qbwHzW9agp8cBuesShxqCQU6xJOCIREr6WmHiUZA4ppSG'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b95af448-7f77-4d06-a87f-b28c6559e6a7', '50d6a493-7898-473d-8287-137229593da9', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$7NIWVE8O/X06gxB4TNXvTeNmjIxUCqMretjcPe6edTb8zw4h7r0Yi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('19dd63c5-faab-409d-85aa-b71b8da16c34', '50d6a493-7898-473d-8287-137229593da9', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$sUjJoWx3gc5N0z2kVqDsXe3cAGTfLAPBgRsETyX.B5tQvJaQnO9Lq'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d9a38c89-9f32-476a-9b7c-d41561f44c94', '50d6a493-7898-473d-8287-137229593da9', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$YGJUM/DvwbSnsENVHf58IeGyqiVnQlFPtKlzc2aSot6c60t23OqKe'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4096cb94-aeae-437e-9893-311968435c5b', '50d6a493-7898-473d-8287-137229593da9', 'Log Analyzer', 'Make 5 requests to nginx. Then run: cat /var/log/nginx/access.log | tail -5 | wc -l. How many access log entries?', 75, '$2b$10$d8wMBBayYvuEa8vBuiG2o.ybUoUFzS8IsgcnZ/eyR.dedMaKeSI46'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c8e36aa6-0446-442c-ba5a-6be0520ed136', '50d6a493-7898-473d-8287-137229593da9', 'Rewrite Master', 'Add to your server config: location /old { return 301 /new; }. Create /var/www/mysite/new.html with "Redirected". Reload. Run: curl -s localhost:9090/old. What is the content after redirect?', 100, '$2b$10$1UqEa7IxxB79xi/UjwFC1up96bJbFk1KCbUYPjIVGbNQo4Rw0jWSi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('32739373-5ad5-4060-b368-ec57de72f4ba', '88de7b45-d1c8-4d13-97df-66805199f591', 'Database Creator', 'Create database shopdb using createdb. Run: psql -l | grep shopdb. What is the output?', 50, '$2b$10$jH8q5JGWa5Ss4t6ErMmH3.jEVvly4EVCr5LEPX2zXbyiheWmoAquO'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2ce38196-8d5a-4ac5-85ba-5ebf3f88cc01', '88de7b45-d1c8-4d13-97df-66805199f591', 'Table Architect', 'Create table products (id SERIAL PRIMARY KEY, name VARCHAR(50), price NUMERIC(10,2), stock INT DEFAULT 0). Run: \d products | wc -l. How many lines of column info?', 75, '$2b$10$P8jCngv9aXEX5ySk3k/WA.KR/4INorv1s4fJUNlcUB50opf6UUCpK'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6ab799f5-c52c-4baf-a4d0-30120ec43e9b', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Inserter', 'Insert into products: ("Laptop", 999.99, 10), ("Mouse", 29.99, 100). Run: SELECT COUNT(*) FROM products. How many rows?', 75, '$2b$10$FX1ygIC5n2DGxDQiwcCSQeHozGbV/H9kpWZQMvqDQazycPzHSButi'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('05ff5787-19ab-491a-8b1a-f133dbf1da4c', '88de7b45-d1c8-4d13-97df-66805199f591', 'Query Master', 'Run: SELECT name FROM products WHERE price > 50 ORDER BY price DESC LIMIT 1. What product?', 75, '$2b$10$I1iXvo7rAX5vlS8oLAYHvu/D6/eU7HHyDJcclxIwaSqhZwWkJ8l.G'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d7d02a0e-0765-4eae-bdb0-7df3039addb9', '88de7b45-d1c8-4d13-97df-66805199f591', 'Index Builder', 'Create index idx_products_name on products(name). Run: \di | grep idx_products_name. What index name is shown?', 100, '$2b$10$MJt8gh3E06TyPapkPH9TU.lyWX0h66ykRBsgYFSV9lrqROdtoViKa'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9cb2c1af-9b36-47ab-a3bc-782bcd4d7a67', '88de7b45-d1c8-4d13-97df-66805199f591', 'Role Manager', 'Create role appuser LOGIN PASSWORD ''secret123''; Grant CONNECT on shopdb to appuser. Run: \du | grep appuser. What is listed?', 100, '$2b$10$ZnlmodwL1ifqLeUwFvnJUuFy3HwefprPm4OnQdKWaoMH66QRR6UiC'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2bce2093-ac33-4d70-ab6b-161610b42759', '88de7b45-d1c8-4d13-97df-66805199f591', 'Backup Creator', 'Run: pg_dump shopdb > /tmp/pgbackup.sql && wc -l /tmp/pgbackup.sql. How many lines?', 100, '$2b$10$UZZXyhGAmcpfgjkgNbKmBeJ9AwNlOBdJmcL5HT8B0D//uw4aIriYW'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4efd8849-fbcc-415f-a9b8-301e4ea8ebf4', '88de7b45-d1c8-4d13-97df-66805199f591', 'Join Artist', 'Create table orders (id SERIAL PRIMARY KEY, product_id INT REFERENCES products(id), quantity INT). Insert 2 orders. Run: SELECT p.name, o.quantity FROM products p JOIN orders o ON p.id=o.product_id. How many rows (excluding header)?', 100, '$2b$10$mZH.gK285jSScv4vaHwMBuOtygtu9pGa1wRo6HllDeFeUfV9yZKPm'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d93dabd0-4a8b-4014-a935-f22b72f2be17', '88de7b45-d1c8-4d13-97df-66805199f591', 'Aggregation Expert', 'Run: SELECT SUM(price * stock) as inventory_value FROM products. What is the total?', 100, '$2b$10$KTLu1W/P.01E0UQNxCQ/cu/y2fgOPY32Q2xcfnraKsBFEL2BnQB4a'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3e0ecad3-d465-4359-a79b-9267fa2720e7', '88de7b45-d1c8-4d13-97df-66805199f591', 'Transaction Tester', 'Run: psql shopdb -c "BEGIN; UPDATE products SET stock=stock-1 WHERE name=''Laptop''; COMMIT;" && psql shopdb -c "SELECT stock FROM products WHERE name=''Laptop''". What is the stock?', 100, '$2b$10$mmQnjU.qF.XzoBJLeIGWUe8Xbo.EttsNsByELXx9F3yOVMwLNWK8u'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('499dc9f7-1964-4220-bca4-c3bfee907918', '88de7b45-d1c8-4d13-97df-66805199f591', 'View Creator', 'Create view cheap_products AS SELECT name, price FROM products WHERE price < 50. Run: SELECT * FROM cheap_products. What product?', 100, '$2b$10$XcWQTFU//T0rYrg1sYnP5uP9WkT6sCiBDijF4Rts7gwFTraCr3mu6'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8a9c6354-b2d8-46be-9f65-33db1d93dcc0', '88de7b45-d1c8-4d13-97df-66805199f591', 'Permission Auditor', 'Run: psql -c "SELECT has_table_privilege(''appuser'', ''products'', ''SELECT'')". What is the result?', 75, '$2b$10$o/mKxNe4S2oJ3br41gaQjuuzdyZYzAKS5LzuOR7uSYuHvDLEYTN56'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ecf68850-a789-42a0-b059-d3a717e19e42', '88de7b45-d1c8-4d13-97df-66805199f591', 'Schema Inspector', 'Run: psql shopdb -c "\dt" | grep -c "product". How many tables match?', 75, '$2b$10$ixI7rehZNA8fv4COI9pz3.Dzn9V6SIijGcsKcfN4KdKqKYq3UXUOu'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7eed6498-c9be-44d5-b58c-d157e36867dd', '88de7b45-d1c8-4d13-97df-66805199f591', 'Serial Expert', 'Insert 3 more products. Run: SELECT MAX(id) FROM products. What is the highest id?', 100, '$2b$10$wjkAeBab5CQxh89ak1MUY.JK1lc/ny.GWEZsQLZBApqvh.4p9gG9i'ON CONFLICT DO NOTHING);
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('bd7c6497-e06a-4fa7-923b-20a61e7fc3e1', '88de7b45-d1c8-4d13-97df-66805199f591', 'Data Updater', 'Run: UPDATE products SET price=price*1.1 WHERE name=''Mouse'' and SELECT price FROM products WHERE name=''Mouse''. What is the new price (rounded to 2 decimals)?', 100, '$2b$10$wCKkhViVt/Qk3lz6DmFBh.Ql1TXxfz6pb0Dzfw0qT384as5fKamo6'ON CONFLICT DO NOTHING);
